 		{"below_min", -0.5, 0.0, 1.0, 0.0},
 		{"above_max", 1.5, 0.0, 1.0, 1.0},
 		{"exact_min", 0.0, 0.0, 1.0, 0.0},
 		{"exact_max", 1.0, 0.0, 1.0, 1.0},
