 	RequestID      string
 	ArbiterSkipped bool
 }

 // FusionOutcomeObserver is the hook invoked once per fusion request
 // with the PanelStreaming outcome (issue #187). Safe for concurrent
 // use, must not block, nil means "no observer". The handler does not
