 	}

 	hits, misses := cached.CacheStats()
 	if hits != 0 {
 		t.Errorf("after first Embed, hits = %d, want 0 (miss)", hits)
 	}
 	if misses != 1 {
 		t.Errorf("after first Embed, misses = %d, want 1", misses)
