 func TestConfidenceSlidingWindowExpiry(t *testing.T) {
 	cs := newTestConfidenceStore(t, 5, time.Hour)
 	old := time.Now().UTC().Add(-2 * time.Hour) // outside the 1h window
 	for i := 0; i < 8; i++ {
